//! W6: the save side of the swap (weather design section 6, "Why saves do
//! not break"). A save keeps a [`WeatherManifest`]: which block and version,
//! the recorded pins and the authored events, never bulk weather. Swapping
//! blocks is a manifest change with a shown difference: climate averages are
//! compared against [`TOLERANCE`], unrecorded weather is regenerated by the
//! new block, and every pin is carried over and checked to be honoured.
//! Switching back gives the original manifest, and so the original weather.

use crate::conditions::Conditions;
use crate::contract::*;
use crate::rules::{self, RuleBlock};
use crate::zonal::{self, ZonalBlock};
use serde::{Deserialize, Serialize};
use sse_core::Address;
use sse_surface::atlas::TileKey;

/// A pin on one world: a recorded system or an authored GM event.
#[derive(Clone, PartialEq, Debug, Serialize, Deserialize)]
pub struct WorldPin {
    pub world: Address,
    pub pin: Pin,
}

/// What a campaign save stores about weather.
#[derive(Clone, PartialEq, Debug, Serialize, Deserialize)]
pub struct WeatherManifest {
    pub block: BlockId,
    /// Systems that were seen and named (`evidence` drawn or pinned).
    #[serde(default)]
    pub pins: Vec<WorldPin>,
    /// GM orders and triggered storms (`evidence: "authored"`).
    #[serde(default)]
    pub authored: Vec<WorldPin>,
}

impl WeatherManifest {
    pub fn new(block: BlockId) -> Self {
        WeatherManifest {
            block,
            pins: vec![],
            authored: vec![],
        }
    }

    /// Everything a block must honour on one world: recorded, then authored.
    pub fn pins_for(&self, world: &Address) -> Vec<Pin> {
        self.pins
            .iter()
            .chain(&self.authored)
            .filter(|p| &p.world == world)
            .map(|p| p.pin.clone())
            .collect()
    }
}

/// The blocks this build can run, by id and version.
pub fn registry() -> Vec<BlockId> {
    vec![
        BlockId {
            id: rules::BLOCK_ID.into(),
            version: rules::BLOCK_VERSION.into(),
            level: "rule".into(),
        },
        BlockId {
            id: zonal::BLOCK_ID.into(),
            version: zonal::BLOCK_VERSION.into(),
            level: "simulated".into(),
        },
    ]
}

/// The block a manifest names, built from the pack stack. An id or version
/// this build does not have is an error, never a silent substitute: old
/// saves keep their old block until the GM chooses to move.
pub fn block_for(
    stack: &[sse_pack::PackManifest],
    id: &BlockId,
) -> Result<Box<dyn WeatherBlock>, String> {
    match (id.id.as_str(), id.version.as_str()) {
        (rules::BLOCK_ID, rules::BLOCK_VERSION) => Ok(Box::new(RuleBlock::from_packs(stack)?)),
        (zonal::BLOCK_ID, zonal::BLOCK_VERSION) => Ok(Box::new(ZonalBlock::from_packs(stack)?)),
        _ => Err(format!(
            "no weather block {} version {} in this build (have {})",
            id.id,
            id.version,
            registry()
                .iter()
                .map(|b| format!("{} {}", b.id, b.version))
                .collect::<Vec<_>>()
                .join(", ")
        )),
    }
}

/// The climate difference on one world.
#[derive(Clone, PartialEq, Debug, Serialize, Deserialize)]
pub struct WorldDiff {
    pub world: String,
    pub cloud_from: f64,
    pub cloud_to: f64,
    pub precip_from_m_yr: f64,
    pub precip_to_m_yr: f64,
    /// Relative change of mean precipitation; `None` when the old block
    /// has none (then any rain at all is outside tolerance).
    pub precip_rel: Option<f64>,
    pub cloud_within: bool,
    pub precip_within: bool,
    pub condensate_from: String,
    pub condensate_to: String,
    pub rain_cells_from: u32,
    pub rain_cells_to: u32,
    /// Largest difference of any one band's cloud cover (shown, not tested).
    pub max_band_cloud_diff: f64,
    pub lines: Vec<String>,
}

impl WorldDiff {
    pub fn within(&self) -> bool {
        self.cloud_within && self.precip_within
    }
}

/// Whether a carried-over pin is honoured by the new block.
#[derive(Clone, PartialEq, Debug, Serialize, Deserialize)]
pub struct PinCheck {
    pub world: String,
    pub id: String,
    /// Days it was asked for, inside its life.
    pub days: Vec<f64>,
    /// `None` when the pin's world was not among the conditions given.
    pub kept: Option<bool>,
}

#[derive(Clone, PartialEq, Debug, Serialize, Deserialize)]
pub struct SwapReport {
    pub from: BlockId,
    pub to: BlockId,
    pub worlds: Vec<WorldDiff>,
    pub pins: Vec<PinCheck>,
    /// The shown difference, in plain lines.
    pub lines: Vec<String>,
    pub within_tolerance: bool,
    pub pins_kept: bool,
    /// The manifest after the swap: the new block, every pin carried over.
    pub manifest: WeatherManifest,
}

fn pct(x: f64) -> String {
    format!("{:+.0} %", 100.0 * x)
}

/// Compare two blocks' climate averages on one world.
pub fn compare(from: &dyn WeatherBlock, to: &dyn WeatherBlock, c: &Conditions) -> WorldDiff {
    let (a, b) = (from.climate(c), to.climate(c));
    let tol = TOLERANCE;
    let dc = b.cloud_cover_mean - a.cloud_cover_mean;
    let cloud_within = dc.abs() <= tol.cloud_cover;
    let precip_rel = (a.precip_mean_m_yr > 1e-12)
        .then(|| (b.precip_mean_m_yr - a.precip_mean_m_yr) / a.precip_mean_m_yr);
    let precip_within = match precip_rel {
        Some(r) => r.abs() <= tol.precip_rel,
        None => b.precip_mean_m_yr <= 1e-12,
    };
    let max_band = a
        .bands
        .iter()
        .zip(&b.bands)
        .map(|(x, y)| (x.cloud_cover - y.cloud_cover).abs())
        .fold(0.0, f64::max);
    let w = &c.label;
    let mut lines = vec![];
    let verdict = |ok: bool| {
        if ok {
            "within tolerance"
        } else {
            "outside tolerance"
        }
    };
    lines.push(format!(
        "{w}: cloud {:.2} -> {:.2} ({:+.2}, {} of ±{:.2}).",
        a.cloud_cover_mean,
        b.cloud_cover_mean,
        dc,
        verdict(cloud_within),
        tol.cloud_cover
    ));
    lines.push(match precip_rel {
        Some(r) => format!(
            "{w}: rain {:.3} -> {:.3} m/yr ({}, {} of ±{:.0} %).",
            a.precip_mean_m_yr,
            b.precip_mean_m_yr,
            pct(r),
            verdict(precip_within),
            100.0 * tol.precip_rel
        ),
        None => format!(
            "{w}: rain {:.3} -> {:.3} m/yr ({}; the old block has none).",
            a.precip_mean_m_yr,
            b.precip_mean_m_yr,
            verdict(precip_within)
        ),
    });
    if a.condensate != b.condensate {
        lines.push(format!(
            "{w}: cloud of {} -> {}.",
            if a.condensate.is_empty() {
                "nothing"
            } else {
                &a.condensate
            },
            if b.condensate.is_empty() {
                "nothing"
            } else {
                &b.condensate
            }
        ));
    }
    if a.rain_cells != b.rain_cells {
        lines.push(format!(
            "{w}: rain alternates wet and dry {} -> {} times pole to equator (erosion's rain_cells).",
            a.rain_cells, b.rain_cells
        ));
    }
    if max_band > tol.cloud_cover {
        lines.push(format!(
            "{w}: cloud moves between latitudes, up to {:.2} in one band.",
            max_band
        ));
    }
    WorldDiff {
        world: w.clone(),
        cloud_from: a.cloud_cover_mean,
        cloud_to: b.cloud_cover_mean,
        precip_from_m_yr: a.precip_mean_m_yr,
        precip_to_m_yr: b.precip_mean_m_yr,
        precip_rel,
        cloud_within,
        precip_within,
        condensate_from: a.condensate,
        condensate_to: b.condensate,
        rain_cells_from: a.rain_cells,
        rain_cells_to: b.rain_cells,
        max_band_cloud_diff: max_band,
        lines,
    }
}

/// Days inside a pin's life to check it on: its birth and its middle (or a
/// day later for a permanent one).
fn pin_days(p: &Pin) -> Vec<f64> {
    let s = &p.system;
    // "Always there" systems (born f64::MIN) are checked from the epoch.
    let born = if s.born <= f64::MIN / 2.0 {
        0.0
    } else {
        s.born
    };
    let mid = if s.ends >= f64::MAX / 2.0 {
        born + 1.0
    } else {
        0.5 * (born + s.ends)
    };
    let mut d = vec![born];
    if mid > born && mid < s.ends {
        d.push(mid);
    }
    d
}

/// The new block honours a pin on a day: the same system, track and life.
fn honoured(b: &dyn WeatherBlock, c: &Conditions, pins: &[Pin], p: &Pin, day: f64) -> bool {
    b.systems(c, Date { day }, pins).iter().any(|s| {
        s.id == p.id
            && s.kind == p.system.kind
            && s.track == p.system.track
            && s.born == p.system.born
            && s.ends == p.system.ends
    })
}

/// Swap a campaign's weather block. `worlds` are the conditions of the
/// worlds the campaign has met; the report compares each and checks every
/// pin on them. The swap itself never fails on a difference: it shows it,
/// and the GM decides.
pub fn swap(
    stack: &[sse_pack::PackManifest],
    manifest: &WeatherManifest,
    worlds: &[Conditions],
    to: &BlockId,
) -> Result<SwapReport, String> {
    let old = block_for(stack, &manifest.block)?;
    let new = block_for(stack, to)?;
    let mut lines = vec![format!(
        "Weather block {} {} ({}) -> {} {} ({}).",
        manifest.block.id,
        manifest.block.version,
        manifest.block.level,
        to.id,
        to.version,
        to.level
    )];
    let diffs: Vec<WorldDiff> = worlds
        .iter()
        .map(|c| compare(old.as_ref(), new.as_ref(), c))
        .collect();
    for d in &diffs {
        lines.extend(d.lines.iter().cloned());
    }
    let mut checks = vec![];
    for wp in manifest.pins.iter().chain(&manifest.authored) {
        let c = worlds.iter().find(|c| c.address == wp.world);
        let days = pin_days(&wp.pin);
        let kept = c.map(|c| {
            let pins = manifest.pins_for(&wp.world);
            days.iter()
                .all(|d| honoured(new.as_ref(), c, &pins, &wp.pin, *d))
        });
        let label = c
            .map(|c| c.label.clone())
            .unwrap_or_else(|| wp.world.to_string());
        let what = if wp.pin.name.is_empty() {
            wp.pin.id.clone()
        } else {
            format!("{} ({})", wp.pin.name, wp.pin.id)
        };
        lines.push(match kept {
            Some(true) => format!(
                "{label}: {} {what} carried over and honoured.",
                wp.pin.system.kind
            ),
            Some(false) => format!(
                "{label}: {} {what} carried over but NOT honoured by the new block.",
                wp.pin.system.kind
            ),
            None => format!(
                "{label}: {} {what} carried over (world not checked).",
                wp.pin.system.kind
            ),
        });
        checks.push(PinCheck {
            world: label,
            id: wp.pin.id.clone(),
            days,
            kept,
        });
    }
    let within = diffs.iter().all(|d| d.within());
    let pins_kept = checks.iter().all(|p| p.kept != Some(false));
    let outside: Vec<&str> = diffs
        .iter()
        .filter(|d| !d.within())
        .map(|d| d.world.as_str())
        .collect();
    lines.push(if outside.is_empty() {
        "Every climate average stays within tolerance; unrecorded weather is regenerated by the new block.".into()
    } else {
        format!(
            "Outside tolerance on {}; unrecorded weather is regenerated by the new block.",
            outside.join(", ")
        )
    });
    let mut next = manifest.clone();
    next.block = to.clone();
    Ok(SwapReport {
        from: manifest.block.clone(),
        to: to.clone(),
        worlds: diffs,
        pins: checks,
        lines,
        within_tolerance: within,
        pins_kept,
        manifest: next,
    })
}

/// Digest of what a manifest's block produces on a world: climate, a field
/// tile and the systems on the given days (the "restored exactly" check).
pub fn weather_digest(
    stack: &[sse_pack::PackManifest],
    manifest: &WeatherManifest,
    c: &Conditions,
    days: &[f64],
    key: TileKey,
    n: u32,
) -> Result<String, String> {
    let b = block_for(stack, &manifest.block)?;
    let pins = manifest.pins_for(&c.address);
    let out: Vec<serde_json::Value> = days
        .iter()
        .map(|d| {
            let date = Date { day: *d };
            serde_json::json!({
                "field": b.field(c, date, key, n, &pins),
                "systems": b.systems(c, date, &pins),
            })
        })
        .collect();
    let text = serde_json::to_string(&serde_json::json!({
        "block": b.id(), "climate": b.climate(c), "days": out,
    }))
    .map_err(|e| e.to_string())?;
    Ok(sse_core::ContentHash::of(&text)
        .map_err(|e| format!("{e:?}"))?
        .hex())
}

